import React, { useState, useEffect } from "react";
import { Rating, CircularProgress, Box, Typography, Grid, Card, CardContent, Avatar } from "@mui/material";

const Testimonial = () => {
  const [testimonials, setTestimonials] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  // Replace this with your actual Google Apps Script URL
  const GOOGLE_SCRIPT_URL = "https://script.google.com/macros/s/AKfycbygHNXsLLG4IQumt-jbA5S6fFeNq8nykltefQxNKI1LLdetvnKl6qhLXmqNzPVZZpO7/exec";

  // Fetch testimonials from Google Apps Script
  const fetchTestimonials = async () => {
    try {
      setLoading(true);
      setError(null);
      
      const params = new URLSearchParams({
        action: "getTestimonials"
      });
      
      const url = `${GOOGLE_SCRIPT_URL}?${params.toString()}`;
      const response = await fetch(url);
      
      if (!response.ok) {
        throw new Error(`Failed to fetch testimonials: ${response.status}`);
      }
      
      const data = await response.json();
      
      if (data.success && data.testimonials) {
        setTestimonials(data.testimonials);
      } else {
        throw new Error(data.message || "No testimonials found");
      }
    } catch (err) {
      console.error("Error fetching testimonials:", err);
      setError(err.message);
      // Fallback to sample data if API fails
      setTestimonials(getSampleTestimonials());
    } finally {
      setLoading(false);
    }
  };

  // Sample fallback data
  const getSampleTestimonials = () => [
    {
      name: "John Doe",
      rating: 5,
      comment: "Excellent coaching and facilities! My game improved significantly.",
      photo: null,
      timestamp: "2024-01-15"
    },
    {
      name: "Sarah Smith",
      rating: 4,
      comment: "Great academy with professional trainers. Highly recommended!",
      photo: null,
      timestamp: "2024-01-10"
    },
    {
      name: "Mike Johnson",
      rating: 5,
      comment: "Best table tennis academy in town. My kids love it here!",
      photo: null,
      timestamp: "2024-01-05"
    }
  ];

  useEffect(() => {
    fetchTestimonials();
  }, []);

  if (loading) {
    return (
      <Box sx={{ 
        display: "flex", 
        justifyContent: "center", 
        alignItems: "center", 
        minHeight: "400px",
        background: "linear-gradient(135deg, rgba(0,0,0,0.9) 0%, rgba(50,50,50,0.95) 100%)",
        color: "white"
      }}>
        <Box sx={{ textAlign: "center" }}>
          <CircularProgress sx={{ color: "#FF9800", mb: 2 }} />
          <Typography variant="h6">Loading testimonials...</Typography>
        </Box>
      </Box>
    );
  }

  if (error && testimonials.length === 0) {
    return (
      <Box sx={{ 
        textAlign: "center", 
        minHeight: "400px",
        background: "linear-gradient(135deg, rgba(0,0,0,0.9) 0%, rgba(50,50,50,0.95) 100%)",
        color: "white",
        padding: 4
      }}>
        <Typography variant="h4" color="error" gutterBottom>
          Error Loading Testimonials
        </Typography>
        <Typography variant="body1" sx={{ color: "rgba(255,255,255,0.7)", mb: 3 }}>
          {error}
        </Typography>
        <button 
          onClick={fetchTestimonials}
          style={{
            background: "#FF9800",
            color: "white",
            border: "none",
            padding: "10px 20px",
            borderRadius: "5px",
            cursor: "pointer"
          }}
        >
          Try Again
        </button>
      </Box>
    );
  }

  return (
    <Box 
      id="testimonials"
      sx={{ 
        background: "linear-gradient(135deg, rgba(0,0,0,0.9) 0%, rgba(50,50,50,0.95) 100%)",
        color: "white",
        padding: { xs: 4, md: 8 },
        minHeight: "100vh"
      }}
    >
      <Typography 
        variant="h2" 
        component="h1" 
        sx={{ 
          textAlign: "center", 
          mb: 6,
          fontFamily: "'AlanSans', sans-serif",
          fontWeight: 700,
          background: "linear-gradient(45deg, #FF9800 30%, #FF5722 90%)",
          backgroundClip: "text",
          WebkitBackgroundClip: "text",
          color: "transparent"
        }}
      >
        What They've Said
      </Typography>

      <Grid container spacing={4}>
        {testimonials.map((testimonial, index) => (
          <Grid item xs={12} md={6} lg={4} key={index}>
            <Card 
              sx={{ 
                background: "rgba(255,255,255,0.05)",
                backdropFilter: "blur(10px)",
                border: "1px solid rgba(255,255,255,0.1)",
                borderRadius: "12px",
                height: "100%",
                transition: "transform 0.3s ease, box-shadow 0.3s ease",
                "&:hover": {
                  transform: "translateY(-5px)",
                  boxShadow: "0 10px 30px rgba(255,152,0,0.2)"
                }
              }}
            >
              <CardContent sx={{ padding: 3, height: "100%", display: "flex", flexDirection: "column" }}>
                {/* User Info Section */}
                <Box sx={{ display: "flex", alignItems: "center", mb: 2 }}>
                  <Avatar
                    src={testimonial.photo || testimonial.photoPreview}
                    sx={{ 
                      width: 60, 
                      height: 60, 
                      mr: 2,
                      border: "2px solid #FF9800"
                    }}
                  >
                    {testimonial.name ? testimonial.name.charAt(0).toUpperCase() : "U"}
                  </Avatar>
                  <Box>
                    <Typography 
                      variant="h6" 
                      sx={{ 
                        fontWeight: 600,
                        fontFamily: "'AlanSans', sans-serif"
                      }}
                    >
                      {testimonial.name}
                    </Typography>
                    <Rating 
                      value={testimonial.rating} 
                      readOnly 
                      size="small"
                      sx={{ 
                        color: "#FF9800",
                        "& .MuiRating-iconFilled": { color: "#FF9800" }
                      }}
                    />
                    {testimonial.timestamp && (
                      <Typography 
                        variant="caption" 
                        sx={{ 
                          color: "rgba(255,255,255,0.5)",
                          display: "block",
                          mt: 0.5
                        }}
                      >
                        {new Date(testimonial.timestamp).toLocaleDateString()}
                      </Typography>
                    )}
                  </Box>
                </Box>

                {/* Feedback Section */}
                <Box sx={{ flexGrow: 1 }}>
                  <Typography 
                    variant="body1" 
                    sx={{ 
                      color: "rgba(255,255,255,0.9)",
                      lineHeight: 1.6,
                      fontStyle: "italic",
                      position: "relative",
                      "&:before, &:after": {
                        content: '"\\201C"',
                        fontSize: "2rem",
                        color: "#FF9800",
                        opacity: 0.7,
                        position: "absolute",
                      },
                      "&:before": {
                        top: -10,
                        left: -5,
                      },
                      "&:after": {
                        content: '"\\201D"',
                        bottom: -20,
                        right: -5,
                      },
                      padding: "0 10px"
                    }}
                  >
                    {testimonial.comment}
                  </Typography>
                </Box>
              </CardContent>
            </Card>
          </Grid>
        ))}
      </Grid>

      {testimonials.length === 0 && !loading && (
        <Box sx={{ textAlign: "center", mt: 4 }}>
          <Typography variant="h5" sx={{ color: "rgba(255,255,255,0.7)" }}>
            No testimonials yet. Be the first to share your experience!
          </Typography>
        </Box>
      )}
    </Box>
  );
};

export default Testimonial;
